    },
    {
      "description": "candidate_materials.md is updated with new candidate materials identified from online research, including their predicted Tc and synthesis feasibility.",
      "expectedFiles": ["candidate_materials.md"]
    },
    {
      "description": "synthesis_methods.md is updated with new or refined synthesis routes for the proposed compounds, referencing online research.",
      "expectedFiles": ["synthesis_methods.md"]
    },
    {
      "description": "characterization_techniques.md is updated with any new characterization methods or improvements relevant to the proposed compounds.",
      "expectedFiles": ["characterization_techniques.md"]
    },
    {
      "description": "discovery_strategy.md is revised to reflect the updated chemistry and physics, including a prioritization of compound families.",
      "expectedFiles": ["discovery_strategy.md"]
    },
    {
      "description": "roadmap.md is updated with new milestones and timelines for synthesis, characterization, and scaling of the proposed compounds.",
      "expectedFiles": ["roadmap.md"]
    },
    {
      "description": "literature_review.md is updated with at least five new references from online research, including key papers on room-temperature superconductivity.",
      "expectedFiles": ["literature_review.md"]
    },
    {
      "description": "docs/online_research_summary.md is updated with a structured summary of the online research conducted, including key findings, sources, and data.",
      "expectedFiles": ["docs/online_research_summary.md"]
    },
    {
      "description": "docs/manufacturing_scalability.md is updated with an analysis of scalability for the proposed synthesis methods, including challenges and mitigations.",
      "expectedFiles": ["docs/manufacturing_scalability.md"]
    },
    {
      "description": "docs/experimental_protocol_hydride.md is updated with detailed protocols for synthesizing and characterizing hydride-based superconductors if proposed.",
      "expectedFiles": ["docs/experimental_protocol_hydride.md"]
    },
    {
      "description": "docs/novel_mechanism.md is updated with any novel superconducting mechanisms proposed based on online research.",
      "expectedFiles": ["docs/novel_mechanism.md"]
    },
    {
      "description": "scripts/predict_tc.py is updated to include new predictive models or parameters derived from the online research.",
      "expectedFiles": ["scripts/predict_tc.py"]
    },
    {
      "description": "tests/test_predict_tc.py is updated to cover the new predictive models or parameters added to predict_tc.py.",
      "expectedFiles": ["tests/test_predict_tc.py"]
    },
    {
      "description": "data/superconductor_database.json is updated with new entries for the proposed compounds, including relevant properties.",
      "expectedFiles": ["data/superconductor_database.json"]
    }
  ]
}

{
