    {
      "description": "Update synthesis_methods.md with detailed high-pressure synthesis techniques (diamond anvil cell, laser heating) and doping strategies for the new candidate materials.",
      "expectedFiles": ["synthesis_methods.md", "docs/synthesis_methods.md"]
    },
    {
      "description": "Update characterization_techniques.md with methods for verifying superconductivity under high pressure (four-probe resistivity, AC susceptibility, X-ray diffraction) and criteria for confirming room-temperature superconductivity.",
      "expectedFiles": ["characterization_techniques.md", "docs/characterization_techniques.md"]
    },
    {
      "description": "Update discovery_strategy.md with a systematic workflow combining computational screening (e.g., density functional theory, machine learning) and experimental validation, including decision gates.",
      "expectedFiles": ["discovery_strategy.md"]
    },
    {
      "description": "Update proposed_chemistry_physics.md with a comprehensive proposal that identifies at least three candidate compound families, their chemical compositions, doping strategies, predicted Tc, synthesis routes, and underlying physical mechanisms.",
      "expectedFiles": ["proposed_chemistry_physics.md"]
    },
    {
      "description": "Update roadmap.md to include new milestones for the next 12 months, such as computational screening, synthesis of top candidates, and characterization under high pressure.",
      "expectedFiles": ["roadmap.md", "docs/roadmap.md"]
    },
    {
      "description": "Update docs/manufacturing_scalability.md with considerations for scaling up synthesis of room-temperature superconductors (e.g., high-pressure reactors, thin film deposition, stabilization at ambient pressure).",
      "expectedFiles": ["docs/manufacturing_scalability.md"]
    },
    {
      "description": "Update docs/experimental_protocol_hydride.md with detailed step-by-step protocols for synthesizing and characterizing hydride superconductors, including safety precautions and data analysis.",
      "expectedFiles": ["docs/experimental_protocol_hydride.md"]
    },
    {
      "description": "Update docs/challenges_and_mitigations.md with at least three identified challenges (e.g., metastability, high-pressure requirements, reproducibility) and proposed mitigations based on literature.",
      "expectedFiles": ["docs/challenges_and_mitigations.md"]
    }
  ]
}

