# Database of known superconducting critical temperatures (K)
KNOWN_TC = {
    "Nb3Sn": 18.3,
    "NbTi": 9.8,
    "MgB2": 39,
    "YBa2Cu3O7": 93,
    "Bi2Sr2CaCu2O8": 110,
    "HgBa2Ca2Cu3O8": 135,
    "La2-xSrxCuO4": 38,
    "FeSe": 8,
    "LiFeAs": 18,
    "H3S": 203,
    "LaH10": 250,
}

def lookup_tc(formula: str) -> float:
    """Lookup known Tc for a given formula. Returns None if not found."""
    return KNOWN_TC.get(formula, None)

def main():
    import argparse
    parser = argparse.ArgumentParser(description="Predict superconducting critical temperature (Tc).")
    parser.add_argument("--formula", type=str, help="Chemical formula for database lookup")
    parser.add_argument("--theta_D", type=float, help="Debye temperature (K)")
    parser.add_argument("--lambda", dest="lambda_", type=float, help="Electron-phonon coupling constant")
    parser.add_argument("--mu_star", type=float, default=0.13, help="Coulomb pseudopotential (default 0.13)")
    parser.add_argument("--omega_log", type=float, help="Logarithmic average phonon frequency (K)")
    parser.add_argument("--lookup", action="store_true", help="Use database lookup instead of McMillan-Allen-Dynes")
    args = parser.parse_args()
    if args.lookup or args.formula:
        if args.formula:
            tc = lookup_tc(args.formula)
            if tc is not None:
                print(f"Known Tc for {args.formula}: {tc} K")
            else:
                print(f"Formula {args.formula} not found in database.")
        else:
            print("No formula provided for lookup.")
    else:
        if args.theta_D is None or args.lambda_ is None:
            print("Error: --theta_D and --lambda are required for McMillan-Allen-Dynes calculation.")
            sys.exit(1)
        tc = predict_tc_mcmillan_allen_dynes(args.theta_D, args.lambda_, args.mu_star, args.omega_log)
        print(f"Predicted Tc: {tc:.2f} K")

if __name__ == "__main__":
    main()
